mapper.update:
UPDATE sys_task_schedule SET active_slot=#{activeSlot},next_index=#{nextIndex},
  next_generate_at=#{nextGenerateAt},next_attempt_at=#{nextAttemptAt},last_failure=#{lastFailure}
WHERE tenant_id=#{tenantId} AND id=#{id}

mapper.select:
SELECT id,tenant_id,actor_id,actor_org_id FROM sys_task_schedule
WHERE active_slot=1 AND next_generate_at <= #{now} AND next_attempt_at <= #{now}
ORDER BY next_attempt_at,id LIMIT 100

SELECT o.* FROM sys_task_occurrence o JOIN sys_task_occurrence_assignment a
  ON a.occurrence_id=o.id AND a.tenant_id=o.tenant_id
WHERE a.tenant_id=#{tenant} AND a.task_id=#{task}
